BLK_START = "### Фаза 12 (добавлена 2026-09-23"
BLK_END = "### Типовая беседа L"


def rd(rel):
    return (ROOT / rel).read_text(encoding="utf-8")


def wr(rel, text):
    (ROOT / rel).write_text(text, encoding="utf-8")


def res(kind, label, why=""):
    global applied, skipped, failed
    if kind == "ok":
        applied += 1
    elif kind == "skip":
        skipped += 1
    else:
        failed += 1
    print(f"  {kind:5} {label}" + (f": {why}" if why else ""))


def patch(rel, old, new, label):
    text = rd(rel)
    if new in text:
        return res("skip", label)
    if text.count(old) != 1:
        return res("fail", label, f"исходный фрагмент встречается {text.count(old)} раз")
    wr(rel, text.replace(old, new))
    res("ok", label)


def replace_span(rel, start, end, new, label, marker):
    """Заменить текст от начала строки-якоря start до якоря end (исключая)."""
    text = rd(rel)
    if marker in text:
        return res("skip", label)
    s = text.find(start)
    e = text.find(end, s + 1) if s >= 0 else -1
    if s < 0 or e < 0:
        return res("fail", label, "границы не найдены")
    wr(rel, text[:s] + new + text[e:])
    res("ok", label)


def set_addressee(num, addr):
    label = f"D §12 {num} → {addr}"
    text = rd(P07)
    m = re.search(r"^\| " + re.escape(num) + r" \|.*$", text, re.M)
    if not m:
        return res("fail", label, "строка не найдена")
    line = m.group(0)
    cells = line.split(" | ")
    if cells[-2] == addr:
        return res("skip", label)
    cells[-2] = addr
    wr(P07, text.replace(line, " | ".join(cells)))
    res("ok", label)


